def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_last = history[-1][1]

    my_d = 0
    opp_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    nonpunish = 0
    unprovoked = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        opp = history[i][1]
        if prev_my == 'D':
            if opp == 'C':
                nonpunish += 1
        elif opp == 'D':
            unprovoked += 1

    d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            d_streak += 1
        else:
            break

    un_streak = 0
    i = n - 1
    while i >= 0:
        a, b = history[i]
        if a == 'C' and b == 'D':
            if i == 0:
                un_streak += 1
                break
            if history[i - 1][0] == 'C':
                un_streak += 1
            else:
                break
        else:
            break
        i -= 1

    recent10_d = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent10_d += 1

    if d_streak >= 5 or (n < 10 and d_streak >= 3):
        return 'D'
    if (n < 5 and d_streak >= 2) or (n == 1 and opp_last == 'D'):
        return 'D'
    if n >= 10 and recent10_d >= 5:
        return 'D'
    if n >= 10 and opp_d * 100 >= n * 55:
        return 'D'

    if un_streak >= 2:
        return 'D'

    if opp_last == 'C' and nonpunish >= 1:
        if recent10_d <= 4 and opp_d * 5 <= n * 3:
            if unprovoked <= 3 or (n >= 30 and unprovoked * 5 <= n):
                return 'D'

    if opp_last == 'C' and my_d == 0 and opp_d == 0 and 25 <= n < 95:
        return 'D'

    return 'C'
